1	import { OFXParseResult, OFXTransaction } from '@/types/banking';
2	import { roundMoney } from '@/shared/lib/roundMoney';
3	
4	/**
5	 * Parser para arquivos OFX (Open Financial Exchange)
6	 * Formato padrao usado por bancos brasileiros para exportar extratos
7	 */
8	export function parseOFX(content: string): OFXParseResult {
9	  const result: OFXParseResult = {
10	    transactions: [],
11	  };
12	
13	  // Remove headers SGML antes do XML
14	  const xmlStart = content.indexOf('<OFX>');
15	  const data = xmlStart >= 0 ? content.substring(xmlStart) : content;
16	
17	  // Extrair info da conta
18	  result.bankId = extractTag(data, 'BANKID');
19	  result.accountId = extractTag(data, 'ACCTID');
20	  result.accountType = extractTag(data, 'ACCTTYPE');
21	
22	  // Extrair saldo da conta corrente (LEDGERBAL)
23	  const balamt = extractTag(data, 'BALAMT');
24	  if (balamt) result.ledgerBalance = roundMoney(parseFloat(balamt));
25	
26	  // BB (e outros bancos com auto-aplicação) zera a conta corrente movendo
27	  // o dinheiro pra um fundo tipo "Rende Fácil". O OFX padrão só traz o saldo
28	  // do CC (que fica em 0), e o saldo real do fundo aparece como texto em
29	  // <MEMO> ou no fim do arquivo. Tentamos extrair pra somar ao saldo total.
30	  result.investmentBalance = extractInvestmentBalance(data);
31	
32	  result.balance = roundMoney((result.ledgerBalance || 0) + (result.investmentBalance || 0));
33	
34	  // Extrair periodo
35	  const dtstart = extractTag(data, 'DTSTART');
36	  const dtend = extractTag(data, 'DTEND');
37	  if (dtstart) result.startDate = parseOFXDate(dtstart);
38	  if (dtend) result.endDate = parseOFXDate(dtend);
39	
40	  // Extrair transacoes
41	  const stmtTrnRegex = /<STMTTRN>([\s\S]*?)<\/STMTTRN>/gi;
42	  let match;
43	
44	  while ((match = stmtTrnRegex.exec(data)) !== null) {
45	    const block = match[1];
46	    const trnType = extractTag(block, 'TRNTYPE');
47	    const dtPosted = extractTag(block, 'DTPOSTED');
48	    const trnAmt = extractTag(block, 'TRNAMT');
49	    const fitid = extractTag(block, 'FITID');
50	    const name = extractTag(block, 'NAME');
51	    const memo = extractTag(block, 'MEMO');
52	
53	    if (dtPosted && trnAmt && fitid) {
54	      const amount = roundMoney(parseFloat(trnAmt.replace(',', '.')));
55	      const txn: OFXTransaction = {
56	        fitid,
57	        date: parseOFXDate(dtPosted),
58	        amount: roundMoney(Math.abs(amount)),
59	        type: amount >= 0 ? 'credito' : 'debito',
60	        description: (name || memo || '').trim(),
61	        memo: memo?.trim() || undefined,
62	      };
63	      result.transactions.push(txn);
64	    }
65	  }
66	
67	  // Se nao encontrou com tags de fechamento, tenta SGML (sem tags de fechamento)
68	  if (result.transactions.length === 0) {
69	    const sgmlBlocks = data.split('<STMTTRN>').slice(1);
70	    for (const block of sgmlBlocks) {
71	      const endIdx = block.indexOf('<STMTTRN>');
72	      const segment = endIdx >= 0 ? block.substring(0, endIdx) : block.split('</BANKTRANLIST>')[0] || block;
73	
74	      const trnAmt = extractTagSGML(segment, 'TRNAMT');
75	      const dtPosted = extractTagSGML(segment, 'DTPOSTED');
76	      const fitid = extractTagSGML(segment, 'FITID');
77	      const name = extractTagSGML(segment, 'NAME');
78	      const memo = extractTagSGML(segment, 'MEMO');
79	
80	      if (dtPosted && trnAmt && fitid) {
81	        const amount = roundMoney(parseFloat(trnAmt.replace(',', '.')));
82	        const txn: OFXTransaction = {
83	          fitid: fitid.trim(),
84	          date: parseOFXDate(dtPosted.trim()),
85	          amount: roundMoney(Math.abs(amount)),
86	          type: amount >= 0 ? 'credito' : 'debito',
87	          description: (name || memo || '').trim(),
88	          memo: memo?.trim() || undefined,
89	        };
90	        result.transactions.push(txn);
91	      }
92	    }
93	  }
94	
95	  return result;
96	}
