98	// Detecta saldo de fundo de investimento embutido no OFX.
99	// BB Rende Fácil é o caso clássico: o CC fica em 0 (tudo auto-aplica no fundo)
100	// e a única referência do dinheiro real é uma linha de texto no fim do extrato
101	// ou em <MEMO> de transações. Só usamos padrões do BLOCO RESUMO (não casamos
102	// "BB Rende Fácil" puro, porque essa string aparece em transações também e
103	// daria falso positivo pegando valor de movimento como saldo do fundo).
104	//   - "Saldo de fundos de investimento BB RENDE FACIL 16.365,45"  (saldo total)
105	//   - "Invest. Resgate Autom. 16.360,65C"                          (resgatável)
106	// Preferência: saldo total > saldo resgatável (diferença = rendimento não liquidado).
107	function extractInvestmentBalance(text: string): number | undefined {
108	  const saldoTotal = matchMoney(text, /Saldo\s+de\s+fundos?\s+de\s+investimento[^\d-]*([\d.]+,\d{2})/i);
109	  if (saldoTotal && saldoTotal > 0) return roundMoney(saldoTotal);
110	
111	  const resgatavel = matchMoney(text, /Invest(?:imento)?\.?\s+Resgate\s+Autom[áa]?tico?\.?[^\d-]*([\d.]+,\d{2})/i);
112	  if (resgatavel && resgatavel > 0) return roundMoney(resgatavel);
113	
114	  return undefined;
115	}
116	
117	function matchMoney(text: string, pattern: RegExp): number | undefined {
118	  const match = text.match(pattern);
119	  if (!match || !match[1]) return undefined;
120	  const valStr = match[1].replace(/\./g, '').replace(',', '.');
121	  const val = parseFloat(valStr);
122	  return isNaN(val) ? undefined : val;
123	}
124	
125	function extractTag(content: string, tag: string): string | undefined {
126	  // XML style: <TAG>value</TAG>
127	  const xmlRegex = new RegExp(`<${tag}>([^<]*)</${tag}>`, 'i');
128	  const xmlMatch = content.match(xmlRegex);
129	  if (xmlMatch) return xmlMatch[1].trim();
130	
131	  // SGML style: <TAG>value\n
132	  return extractTagSGML(content, tag);
133	}
134	
135	function extractTagSGML(content: string, tag: string): string | undefined {
136	  const sgmlRegex = new RegExp(`<${tag}>([^\\n<]+)`, 'i');
137	  const sgmlMatch = content.match(sgmlRegex);
138	  if (sgmlMatch) return sgmlMatch[1].trim();
139	  return undefined;
140	}
141	
142	function parseOFXDate(dateStr: string): string {
143	  // OFX dates: YYYYMMDDHHMMSS or YYYYMMDD or YYYYMMDDHHMMSS[-3:BRT]
144	  const clean = dateStr.replace(/\[.*\]/, '').trim();
145	  const year = clean.substring(0, 4);
146	  const month = clean.substring(4, 6);
147	  const day = clean.substring(6, 8);
148	  return `${year}-${month}-${day}`;
149	}
