151	/**
152	 * Parser simples para CSV de fatura de cartao
153	 * Aceita formatos comuns: data;descricao;valor ou data,descricao,valor
154	 */
155	export function parseCardCSV(content: string): { data: string; descricao: string; valor: number; parcela_atual?: number; total_parcelas?: number }[] {
156	  const lines = content.trim().split('\n');
157	  const results: { data: string; descricao: string; valor: number; parcela_atual?: number; total_parcelas?: number }[] = [];
158	
159	  // Detectar separador
160	  const separator = lines[0]?.includes(';') ? ';' : ',';
161	
162	  // Detectar header
163	  const firstLine = lines[0]?.toLowerCase() || '';
164	  const hasHeader = firstLine.includes('data') || firstLine.includes('date') || firstLine.includes('descri');
165	  const startIdx = hasHeader ? 1 : 0;
166	
167	  for (let i = startIdx; i < lines.length; i++) {
168	    const line = lines[i].trim();
169	    if (!line) continue;
170	
171	    const parts = line.split(separator).map(p => p.trim().replace(/^"|"$/g, ''));
172	    if (parts.length < 3) continue;
173	
174	    // Tentar encontrar data, descricao, valor
175	    const dateStr = parseFlexibleDate(parts[0]);
176	    const descricao = parts[1];
177	    let valorStr = parts[parts.length - 1].replace(/[R$\s.]/g, '').replace(',', '.');
178	    // Se o penultimo campo parece ser valor (quando tem mais colunas)
179	    if (isNaN(parseFloat(valorStr)) && parts.length > 3) {
180	      valorStr = parts[2].replace(/[R$\s.]/g, '').replace(',', '.');
181	    }
182	    const valor = Math.abs(parseFloat(valorStr));
183	
184	    if (!dateStr || isNaN(valor) || !descricao) continue;
185	
186	    // Detectar parcelas no formato "COMPRA 3/12"
187	    let parcela_atual: number | undefined;
188	    let total_parcelas: number | undefined;
189	    const parcelaMatch = descricao.match(/(\d+)\/(\d+)/);
190	    if (parcelaMatch) {
191	      parcela_atual = parseInt(parcelaMatch[1]);
192	      total_parcelas = parseInt(parcelaMatch[2]);
193	    }
194	
195	    results.push({ data: dateStr, descricao, valor, parcela_atual, total_parcelas });
196	  }
197	
198	  return results;
199	}
200	
201	function parseFlexibleDate(dateStr: string): string | null {
202	  // DD/MM/YYYY
203	  const brMatch = dateStr.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
204	  if (brMatch) return `${brMatch[3]}-${brMatch[2]}-${brMatch[1]}`;
205	
206	  // YYYY-MM-DD
207	  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
208	  if (isoMatch) return dateStr;
209	
210	  // DD/MM/YY
211	  const brShort = dateStr.match(/^(\d{2})\/(\d{2})\/(\d{2})$/);
212	  if (brShort) return `20${brShort[3]}-${brShort[2]}-${brShort[1]}`;
213	
214	  return null;
215	}
