60	// ── Helpers ──
61	
62	// Bank internal charges — these rarely correspond to a conta a pagar/receber
63	const BANK_FEE_PATTERN = /\b(tarifa|tar\.|taxa\b|iof|anuidade|manutencao|cesta\s*de\s*servico|encargo|agrupada)/i;
64	
65	function isBankFee(desc: string): boolean {
66	  return BANK_FEE_PATTERN.test(desc);
67	}
68	
69	// Text normalization for description comparison
70	const BANKING_NOISE = /\b(pix|ted|doc|deb|cred|auto|pag|pagamento|recebido|enviado|transf|transferencia|compra|parcela|parc|ref|nsu|aut|pgto|tar|tarifa|ocorrencia|agrupadas?)\b/gi;
71	const PUNCTUATION = /[*\-/\\.,;:()#[\]{}|'"!?&@=+<>_~^`]/g;
72	const DATE_PATTERN = /\d{2}\/\d{2}\/\d{4}/g;
73	const MULTI_SPACES = /\s{2,}/g;
74	const CNPJ_PATTERN = /(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/g;
75	const CPF_PATTERN = /(\d{3}\.?\d{3}\.?\d{3}-?\d{2})/g;
76	
77	function normalizeDesc(desc: string): string {
78	  return desc
79	    .toLowerCase()
80	    .replace(DATE_PATTERN, ' ')
81	    .replace(PUNCTUATION, ' ')
82	    .replace(BANKING_NOISE, ' ')
83	    .replace(MULTI_SPACES, ' ')
84	    .trim();
85	}
86	
87	function extractDocNumbers(desc: string): string[] {
88	  const cnpjs = desc.match(CNPJ_PATTERN) || [];
89	  const cpfs = desc.match(CPF_PATTERN) || [];
90	  return [...cnpjs, ...cpfs].map(d => d.replace(/[.\-/]/g, ''));
91	}
92	
93	function extractMeaningfulWords(normalized: string): string[] {
94	  return normalized.split(/\s+/).filter(w => w.length > 3);
95	}
96	
97	function calcDescriptionScore(bankDesc: string, contaDesc: string): { score: number; reason: string; hasMatch: boolean } {
98	  // 1) CNPJ/CPF match — strongest signal
99	  const bankDocs = extractDocNumbers(bankDesc);
100	  const contaDocs = extractDocNumbers(contaDesc);
101	  if (bankDocs.length > 0 && contaDocs.length > 0) {
102	    const docMatch = bankDocs.some(bd => contaDocs.includes(bd));
103	    if (docMatch) return { score: 20, reason: 'CNPJ/CPF identico', hasMatch: true };
104	  }
105	
106	  const bankNorm = normalizeDesc(bankDesc);
107	  const contaNorm = normalizeDesc(contaDesc);
108	
109	  // 2) One description contains the other
110	  if (bankNorm.length > 6 && contaNorm.length > 6) {
111	    if (bankNorm.includes(contaNorm) || contaNorm.includes(bankNorm)) {
112	      return { score: 18, reason: 'Descricao contida', hasMatch: true };
113	    }
114	  }
115	
116	  // 3) Word overlap
117	  const bankWords = extractMeaningfulWords(bankNorm);
118	  const contaWords = extractMeaningfulWords(contaNorm);
119	
120	  if (bankWords.length === 0 || contaWords.length === 0) {
121	    return { score: 0, reason: '', hasMatch: false };
122	  }
123	
124	  const matchedWords: string[] = [];
125	  for (const cw of contaWords) {
126	    if (bankWords.some(bw => bw.includes(cw) || cw.includes(bw))) {
127	      matchedWords.push(cw);
128	    }
129	  }
130	
131	  if (matchedWords.length === 0) return { score: 0, reason: '', hasMatch: false };
132	
133	  const ratio = matchedWords.length / contaWords.length;
134	  let score: number;
135	  if (ratio >= 0.5 && matchedWords.length >= 2) score = 15;
136	  else if (matchedWords.length >= 3) score = 12;
137	  else if (matchedWords.length >= 2) score = 8;
138	  else score = 5;
139	
140	  return { score, reason: `Palavras: ${matchedWords.slice(0, 3).join(', ')}`, hasMatch: true };
141	}
