143	function calcPaymentMethodScore(bankDesc: string, contaFormaPgto: string | null): number {
144	  if (!contaFormaPgto) return 0;
145	  const desc = bankDesc.toLowerCase();
146	  if (contaFormaPgto === 'pix' && /pix/i.test(desc)) return 5;
147	  if (contaFormaPgto === 'boleto' && /boleto|titulo|cobranca/i.test(desc)) return 5;
148	  if (contaFormaPgto === 'transferencia' && /ted|doc|transf/i.test(desc)) return 5;
149	  if (contaFormaPgto === 'debito_automatico' && /deb.*auto/i.test(desc)) return 5;
150	  return 0;
151	}
