159	export function useReconciliation() {
160	  const [bankMatches, setBankMatches] = useState<ReconciliationMatch[]>([]);
161	  const [unmatchedTxns, setUnmatchedTxns] = useState<UnmatchedBankTxn[]>([]);
162	  const [cardMatches, setCardMatches] = useState<CreditCardReconciliationMatch[]>([]);
163	  const [loading, setLoading] = useState(false);
164	  const [reconciliationStats, setReconciliationStats] = useState<ReconciliationStats | null>(null);
165	
166	  const findBankMatches = useCallback(async (
167	    accountId: number,
168	  ) => {
169	    setLoading(true);
170	    try {
171	      // 1) Resolve loja_id from the bank account itself
172	      const { data: accountData, error: accErr } = await supabase
173	        .from('bank_accounts')
174	        .select('loja_id')
175	        .eq('id', accountId)
176	        .single();
177	
178	      if (accErr) throw accErr;
179	      const accountLojaId = accountData?.loja_id;
180	
181	      // 2) Get unreconciled bank transactions
182	      const { data: bankTxns, error: bankErr } = await supabase
183	        .from('bank_transactions')
184	        .select('*')
185	        .eq('bank_account_id', accountId)
186	        .eq('conciliado', false)
187	        .order('data', { ascending: false });
188	
189	      if (bankErr) throw bankErr;
190	      if (!bankTxns || bankTxns.length === 0) {
191	        setBankMatches([]);
192	        setUnmatchedTxns([]);
193	        setLoading(false);
194	        return;
195	      }
196	
197	      // 3) Get candidate contas ONLY from the same store
198	      const contasQuery = supabase
199	        .from('contas_pagar_receber')
200	        .select('id, descricao, valor, data_vencimento, data_pagamento, status, tipo, origem, forma_pagamento, data_competencia')
201	        .eq('loja_id', accountLojaId)
202	        .in('status', ['pendente', 'pago', 'recebido'])
203	        .or('forma_pagamento.is.null,forma_pagamento.neq.cartao_credito')
204	        .order('data_vencimento', { ascending: false });
205	
206	      const { data: contas, error: contasErr } = await contasQuery;
207	      if (contasErr) throw contasErr;
208	      const candidateContas = contas || [];
209	
210	      // 4) Get ALL reconciled conta IDs across ALL bank accounts
211	      const { data: allReconciledIds } = await supabase
212	        .from('bank_transactions')
213	        .select('conta_financeira_id')
214	        .eq('conciliado', true)
215	        .not('conta_financeira_id', 'is', null);
216	
217	      const globalUsedContaIds = new Set(
218	        (allReconciledIds || []).map((r: any) => r.conta_financeira_id)
219	      );
220	
221	      // 5) Score all candidate pairs — ULTRA-STRICT: only guaranteed matches
222	      // Requirements: exact value + strong identity (CNPJ/CPF or clear name) + close date
223	      // Anything matched here is removed from the AI pool, so zero false positives.
224	      const allCandidates: ReconciliationMatch[] = [];
225	
226	      for (const txn of bankTxns as BankTransaction[]) {
227	        const txnAmount = Math.abs(txn.valor);
228	        const txnDate = new Date(txn.data + 'T12:00:00');
229	        const isDebit = txn.tipo === 'debito';
230	
231	        // Bank fees never match algorithmically
232	        if (isBankFee(txn.descricao)) continue;
233	
234	        for (const conta of candidateContas) {
235	          if (globalUsedContaIds.has(conta.id)) continue;
236	
237	          // Type must match
238	          const typeMatch = (isDebit && conta.tipo === 'despesa') || (!isDebit && conta.tipo === 'receita');
239	          if (!typeMatch) continue;
240	
241	          // VALUE: must be exact to the cent — no tolerance
242	          const contaAmount = Math.abs(conta.valor);
243	          const valueDiff = Math.abs(txnAmount - contaAmount);
244	          if (valueDiff >= 0.01) continue;
245	
246	          // DATE: max 7 days
247	          let bestDateDiff = 999;
248	          const dates: Date[] = [];
249	          if (conta.data_vencimento) dates.push(new Date(conta.data_vencimento + 'T12:00:00'));
250	          if (conta.data_pagamento) dates.push(new Date(conta.data_pagamento + 'T12:00:00'));
251	          if (conta.data_competencia) dates.push(new Date(conta.data_competencia + 'T12:00:00'));
252	          for (const d of dates) {
253	            const diff = dateDiffDays(txnDate, d);
254	            if (diff < bestDateDiff) bestDateDiff = diff;
255	          }
256	          if (bestDateDiff > 7) continue;
257	
258	          // IDENTITY: must have CNPJ/CPF or strong description match
259	          const descResult = calcDescriptionScore(txn.descricao, conta.descricao);
260	
261	          // Only accept strong signals: CNPJ/CPF (20), description contained (18), or 2+ words (8+)
262	          // Single word match (5) is NOT enough — too risky
263	          if (descResult.score < 8) continue;
264	
265	          // Scoring
266	          const dateScore = bestDateDiff <= 0.5 ? 30 : bestDateDiff <= 1 ? 25 : bestDateDiff <= 3 ? 20 : bestDateDiff <= 5 ? 15 : 10;
267	          const originScore = conta.origem === 'nota_fiscal' ? 5 : 0;
268	          let confidence = 45 + dateScore + descResult.score + originScore;
269	          confidence = Math.min(confidence, 100);
270	
271	          // Only accept high confidence
272	          if (confidence < 80) continue;
273	
274	          const reasons: string[] = ['Valor exato'];
275	          if (bestDateDiff <= 0.5) reasons.push('Mesma data');
276	          else if (bestDateDiff <= 3) reasons.push('Data proxima');
277	          else reasons.push(`${Math.round(bestDateDiff)}d dif`);
278	          if (descResult.reason) reasons.push(descResult.reason);
279	          if (originScore > 0) reasons.push('Origem NF');
280	
281	          allCandidates.push({
282	            bankTxnId: txn.id,
283	            bankTxn: txn,
284	            contaId: conta.id,
285	            contaDescricao: conta.descricao,
286	            contaValor: conta.valor,
287	            contaVencimento: conta.data_vencimento,
288	            contaStatus: conta.status,
289	            contaTipo: conta.tipo,
290	            contaOrigem: conta.origem,
291	            confidence,
292	            matchReason: reasons.join(' | '),
293	          });
294	        }
295	      }
296	
297	      // 6) Greedy assignment: best confidence first, no reuse
298	      allCandidates.sort((a, b) => b.confidence - a.confidence);
299	
300	      const usedBankTxns = new Set<number>();
301	      const usedContas = new Set<string>();
302	      const bestMatches: ReconciliationMatch[] = [];
303	
304	      for (const m of allCandidates) {
305	        if (usedBankTxns.has(m.bankTxnId) || usedContas.has(m.contaId)) continue;
306	        usedBankTxns.add(m.bankTxnId);
307	        usedContas.add(m.contaId);
308	        bestMatches.push(m);
309	      }
310	
311	      // 7) Unmatched
312	      const unmatched: UnmatchedBankTxn[] = (bankTxns as BankTransaction[])
313	        .filter(txn => !usedBankTxns.has(txn.id))
314	        .map(txn => ({ bankTxn: txn }));
315	
316	      setBankMatches(bestMatches);
317	      setUnmatchedTxns(unmatched);
318	    } catch (e) {
319	      handleError(e, { domain: 'financeiro', operation: 'findBankMatches', showToast: false });
320	      toast.error('Erro ao buscar correspondencias');
321	    } finally {
322	      setLoading(false);
323	    }
324	  }, []);
