666	          .single();
667	        tipo = contaData?.tipo;
668	      }
669	
670	      const isReceita = tipo === 'receita';
671	      const updateData: Record<string, any> = {
672	        status: isReceita ? 'recebido' : 'pago',
673	        ...(isReceita ? { data_recebimento: bankTxnDate } : { data_pagamento: bankTxnDate }),
674	      };
675	      const { error: contaErr } = await supabase
676	        .from('contas_pagar_receber')
677	        .update(updateData)
678	        .eq('id', contaId)
679	        .eq('status', 'pendente');
680	      if (contaErr) throw contaErr;
681	
682	      toast.success('Transacao conciliada manualmente');
683	    } catch (e) {
684	      handleError(e, { domain: 'financeiro', operation: 'manualLink', showToast: false });
685	      toast.error('Erro ao conciliar');
686	    }
687	  }, []);
688	
689	  const unlinkTransaction = useCallback(async (
690	    bankTxnId: number,
691	    contaFinanceiraId: string | null,
692	  ) => {
693	    try {
694	      const { error: bankErr } = await supabase
695	        .from('bank_transactions')
696	        .update({ conciliado: false, conta_financeira_id: null })
697	        .eq('id', bankTxnId);
698	      if (bankErr) throw bankErr;
699	
700	      if (contaFinanceiraId) {
701	        // Check if this conta was auto-generated from bank sync
702	        const { data: conta } = await supabase
703	          .from('contas_pagar_receber')
704	          .select('origem')
705	          .eq('id', contaFinanceiraId)
706	          .single();
707	
708	        if (conta?.origem === 'extrato_bancario') {
709	          // Delete auto-generated contas — they have no independent existence
710	          await supabase
711	            .from('contas_pagar_receber')
712	            .delete()
713	            .eq('id', contaFinanceiraId);
714	        } else {
715	          // Reset manually-created contas back to pendente
716	          await supabase
717	            .from('contas_pagar_receber')
718	            .update({ status: 'pendente', data_pagamento: null, data_recebimento: null })
719	            .eq('id', contaFinanceiraId)
720	            .in('status', ['pago', 'recebido']);
721	        }
722	      }
723	
724	      toast.success('Conciliacao desfeita');
725	    } catch (e) {
726	      handleError(e, { domain: 'financeiro', operation: 'unlinkTransaction', showToast: false });
727	      toast.error('Erro ao desfazer conciliacao');
728	    }
729	  }, []);
