731	  const aiReconcile = useCallback(async (accountId: number) => {
732	    setLoading(true);
733	    setReconciliationStats(null);
734	    try {
735	      const { data, error } = await supabase.functions.invoke('ai-reconciliation', {
736	        body: { account_id: accountId },
737	      });
738	
739	      if (error) throw error;
740	      if (data?.error) throw new Error(data.error);
741	
742	      const matches: ReconciliationMatch[] = (data.matches || []).map((m: any) => ({
743	        bankTxnId: m.bankTxnId,
744	        bankTxn: m.bankTxn as BankTransaction,
745	        contaId: m.contaId,
746	        contaDescricao: m.contaDescricao || '',
747	        contaValor: m.contaValor || 0,
748	        contaVencimento: m.contaVencimento || null,
749	        contaStatus: m.contaStatus || '',
750	        contaTipo: m.contaTipo || '',
751	        contaOrigem: m.contaOrigem || '',
752	        confidence: m.confidence || 0,
753	        matchReason: m.matchReason || '',
754	        pass: m.pass || 'algorithmic',
755	      }));
756	
757	      const unmatched: UnmatchedBankTxn[] = (data.unmatched || []).map((u: any) => ({
758	        bankTxn: u.bankTxn as BankTransaction,
759	      }));
760	
761	      setBankMatches(matches);
762	      setUnmatchedTxns(unmatched);
763	      setReconciliationStats(data.stats || null);
764	
765	      const totalMatches = matches.length;
766	      if (totalMatches > 0) {
767	        toast.success(`${totalMatches} correspondencias encontradas (${data.stats?.pass1 || 0} algoritmo, ${(data.stats?.pass2 || 0) + (data.stats?.pass3 || 0)} IA)`);
768	      } else {
769	        toast.info('Nenhuma correspondencia encontrada');
770	      }
771	    } catch (e: any) {
772	      handleError(e, { domain: 'financeiro', operation: 'aiReconcile', showToast: false });
773	      toast.error(`Erro na conciliacao IA: ${(e as any).message || 'Erro desconhecido'}`);
774	    } finally {
775	      setLoading(false);
776	    }
777	  }, []);
778	
779	  return {
780	    bankMatches,
781	    unmatchedTxns,
782	    cardMatches,
783	    loading,
784	    reconciliationStats,
785	    findBankMatches,
786	    aiReconcile,
787	    confirmBankMatch,
788	    confirmAllBankMatches,
789	    dismissMatch,
790	    markConciliadoAlone,
791	    bulkMarkConciliadoAlone,
792	    findCardMatches,
793	    confirmCardMatch,
794	    searchContas,
795	    manualLink,
796	    unlinkTransaction,
797	  };
